from solution import remove_odd


def test_issue_example_given():
    """Example from issue: remove_odd([1,2,3]) == [2]."""
    assert remove_odd([1, 2, 3]) == [2]  # 1%2=1 removed, 2%2=0 kept, 3%2=1 removed


def test_issue_empty_list():
    """Remove odd numbers from a given list handles empty input."""
    assert remove_odd([]) == []  # no elements: 0 kept, 0 removed


def test_issue_all_odd_removed():
    """Remove odd numbers from a given list returns empty when all odd."""
    assert remove_odd([1, 3, 5]) == []  # 1%2=1 removed, 3%2=1 removed, 5%2=1 removed


def test_issue_all_even_kept():
    """Remove odd numbers from a given list keeps all evens."""
    assert remove_odd([2, 4, 6]) == [2, 4, 6]  # 2%2=0 kept, 4%2=0 kept, 6%2=0 kept


def test_issue_zero_is_even():
    """Remove odd numbers from a given list keeps zero as even."""
    assert remove_odd([0, 1, 2]) == [0, 2]  # 0%2=0 kept, 1%2=1 removed, 2%2=0 kept


def test_issue_negative_numbers():
    """Remove odd numbers from a given list handles negatives."""
    assert remove_odd([-4, -3, -2, -1, 0]) == [-4, -2, 0]  # -4%2=0 kept, -3%2=1 removed, -2%2=0 kept, -1%2=1 removed, 0%2=0 kept


def test_issue_order_preserved_value_not_index():
    """Remove odd numbers from a given list preserves order by value."""
    assert remove_odd([3, 2, 5, 4]) == [2, 4]  # 3%2=1 removed, 2%2=0 kept, 5%2=1 removed, 4%2=0 kept


def test_issue_single_odd():
    """Remove odd numbers from a given list removes a lone odd."""
    assert remove_odd([7]) == []  # 7%2=1 removed


def test_issue_single_even():
    """Remove odd numbers from a given list keeps a lone even."""
    assert remove_odd([8]) == [8]  # 8%2=0 kept


def test_issue_mixed_around_zero():
    """Remove odd numbers from a given list filters values just above and below zero."""
    assert remove_odd([-1, 0, 1, 2]) == [0, 2]  # -1%2=1 removed, 0%2=0 kept, 1%2=1 removed, 2%2=0 kept


def test_contract_returns_list():
    """Documented rule: function removes odds from a list and returns a list."""
    result = remove_odd([1, 2, 3])  # 1%2=1 removed, 2%2=0 kept, 3%2=1 removed
    assert isinstance(result, list)


def test_contract_callable_interface():
    """Documented rule: solution.remove_odd(l) takes a given list."""
    assert callable(remove_odd)  # interface exposes remove_odd(l) as callable
